import React, { useState, useEffect } from 'react';
import Navbar from '../components/Navbar';
import { FaPlus, FaCheckCircle, FaCircle, FaTrash, FaPlay, FaPause, FaRedo, FaHourglassHalf } from 'react-icons/fa';

function Habits() {
  const [habits, setHabits] = useState([
    { id: 1, name: '💧 Drink Water', target: '8 glasses', completed: false, timerActive: false, timerRemaining: 0, timerDuration: 0 },
    { id: 2, name: '🏃 Exercise', target: '30 mins', completed: false, timerActive: false, timerRemaining: 30, timerDuration: 30 },
    { id: 3, name: '🧘 Meditate', target: '10 mins', completed: false, timerActive: false, timerRemaining: 10, timerDuration: 10 },
    { id: 4, name: '📚 Read Book', target: '20 pages', completed: false, timerActive: false, timerRemaining: 0, timerDuration: 0 },
  ]);
  const [newHabit, setNewHabit] = useState('');
  const [newHabitTime, setNewHabitTime] = useState('');
  const [celebrating, setCelebrating] = useState(null);

  // Countdown timer effect
  useEffect(() => {
    const intervals = [];
    habits.forEach(habit => {
      if (habit.timerActive && habit.timerRemaining > 0) {
        const interval = setInterval(() => {
          setHabits(prev => prev.map(h => 
            h.id === habit.id 
              ? { ...h, timerRemaining: Math.max(h.timerRemaining - 1, 0) }
              : h
          ));
        }, 60000); // Update every minute
        intervals.push(interval);
      } else if (habit.timerActive && habit.timerRemaining <= 0 && habit.timerDuration > 0) {
        // Timer completed!
        setHabits(prev => prev.map(h => 
          h.id === habit.id 
            ? { ...h, timerActive: false, completed: true }
            : h
        ));
        setCelebrating(habit.id);
        setTimeout(() => setCelebrating(null), 3000);
      }
    });
    
    return () => intervals.forEach(clearInterval);
  }, [habits]);

  const toggleHabit = (id) => {
    const habit = habits.find(h => h.id === id);
    if (!habit.completed) {
      setHabits(habits.map(habit =>
        habit.id === id ? { ...habit, completed: !habit.completed, timerActive: false } : habit
      ));
      setCelebrating(id);
      setTimeout(() => setCelebrating(null), 2000);
    }
  };

  const startTimer = (id) => {
    setHabits(habits.map(habit =>
      habit.id === id && habit.timerDuration > 0 && !habit.completed && habit.timerRemaining > 0
        ? { ...habit, timerActive: true }
        : habit
    ));
  };

  const pauseTimer = (id) => {
    setHabits(habits.map(habit =>
      habit.id === id ? { ...habit, timerActive: false } : habit
    ));
  };

  const resetTimer = (id) => {
    const habit = habits.find(h => h.id === id);
    setHabits(habits.map(habit =>
      habit.id === id 
        ? { ...habit, timerRemaining: habit.timerDuration, timerActive: false, completed: false } 
        : habit
    ));
  };

  const addHabit = () => {
    if (newHabit.trim()) {
      const timeInMinutes = parseInt(newHabitTime) || 0;
      setHabits([...habits, {
        id: Date.now(),
        name: newHabit,
        target: timeInMinutes > 0 ? `${timeInMinutes} mins` : 'Daily',
        completed: false,
        timerActive: false,
        timerRemaining: timeInMinutes,
        timerDuration: timeInMinutes
      }]);
      setNewHabit('');
      setNewHabitTime('');
    }
  };

  const deleteHabit = (id) => {
    setHabits(habits.filter(habit => habit.id !== id));
  };

  const formatTime = (minutes) => {
    if (minutes <= 0) return '0m';
    const hrs = Math.floor(minutes / 60);
    const mins = minutes % 60;
    if (hrs > 0) return `${hrs}h ${mins}m`;
    return `${mins}m`;
  };

  const getTimerProgress = (habit) => {
    if (habit.timerDuration === 0) return 0;
    return ((habit.timerRemaining / habit.timerDuration) * 100);
  };

  const completedCount = habits.filter(h => h.completed).length;

  return (
    <div style={styles.container}>
      <Navbar />
      
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}>✅ Habit Tracker</h1>
          <p style={styles.subtitle}>Complete your habits before time runs out!</p>
        </div>

        {celebrating && (
          <div style={styles.celebrationOverlay}>
            <div style={styles.celebrationText}>
              🎉 Great Job! 🎉
            </div>
          </div>
        )}

        <div style={styles.progressCard}>
          <div style={styles.progressInfo}>
            <span>📊 Daily Progress</span>
            <span>{completedCount}/{habits.length} completed</span>
          </div>
          <div style={styles.progressBar}>
            <div style={{...styles.progressFill, width: `${(completedCount/habits.length)*100}%`}} />
          </div>
        </div>

        <div style={styles.addHabitCard}>
          <div style={styles.addHabitInputs}>
            <input
              type="text"
              placeholder="Add a new habit..."
              style={styles.input}
              value={newHabit}
              onChange={(e) => setNewHabit(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && addHabit()}
            />
            <input
              type="number"
              placeholder="Minutes to complete"
              style={styles.timeInput}
              value={newHabitTime}
              onChange={(e) => setNewHabitTime(e.target.value)}
            />
          </div>
          <button onClick={addHabit} style={styles.addBtn}>
            <FaPlus /> Add Habit
          </button>
        </div>

        <div style={styles.habitsList}>
          {habits.map(habit => {
            const isUrgent = habit.timerRemaining <= 5 && habit.timerRemaining > 0 && !habit.completed;
            const progress = getTimerProgress(habit);
            
            return (
              <div key={habit.id} style={{...styles.habitItem, ...(habit.completed ? styles.habitCompleted : {}), ...(isUrgent ? styles.habitUrgent : {})}}>
                <div style={styles.habitLeft}>
                  <div onClick={() => toggleHabit(habit.id)} style={styles.checkbox}>
                    {habit.completed ? 
                      <FaCheckCircle color="#2ecc71" size={28} /> : 
                      <FaCircle color="#ccc" size={28} />
                    }
                  </div>
                  <div style={styles.habitInfo}>
                    <h4 style={{...styles.habitName, textDecoration: habit.completed ? 'line-through' : 'none'}}>
                      {habit.name}
                    </h4>
                    <p style={styles.habitTarget}>🎯 {habit.target}</p>
                    
                    {habit.timerDuration > 0 && !habit.completed && (
                      <div style={styles.timerSection}>
                        <div style={styles.timerBar}>
                          <div style={{...styles.timerFill, width: `${progress}%`}} />
                        </div>
                        <div style={styles.timerInfo}>
                          <FaHourglassHalf size={12} color={isUrgent ? '#e74c3c' : '#667eea'} />
                          <span style={{...styles.timerRemainingText, ...(isUrgent ? styles.urgentText : {})}}>
                            ⏰ {formatTime(habit.timerRemaining)} left
                          </span>
                          <span style={styles.timerTotalText}> / {formatTime(habit.timerDuration)}</span>
                        </div>
                        <div style={styles.timerControls}>
                          {!habit.timerActive && habit.timerRemaining > 0 && (
                            <button onClick={() => startTimer(habit.id)} style={styles.timerBtnPlay}>
                              <FaPlay size={12} /> Start
                            </button>
                          )}
                          {habit.timerActive && (
                            <button onClick={() => pauseTimer(habit.id)} style={styles.timerBtnPause}>
                              <FaPause size={12} /> Pause
                            </button>
                          )}
                          {habit.timerRemaining < habit.timerDuration && (
                            <button onClick={() => resetTimer(habit.id)} style={styles.timerBtnReset}>
                              <FaRedo size={12} /> Reset
                            </button>
                          )}
                        </div>
                      </div>
                    )}
                    
                    {habit.timerDuration > 0 && habit.completed && (
                      <div style={styles.completedBadge}>
                        ✅ Completed in time!
                      </div>
                    )}
                  </div>
                </div>
                <button onClick={() => deleteHabit(habit.id)} style={styles.deleteBtn}>
                  <FaTrash color="#e74c3c" size={18} />
                </button>
              </div>
            );
          })}
        </div>

        {habits.length === 0 && (
          <div style={styles.emptyState}>
            <p>✨ No habits yet. Add your first habit above! ✨</p>
          </div>
        )}

        <div style={styles.tipsCard}>
          <div style={styles.tipIcon}>⏰</div>
          <div style={styles.tipContent}>
            <h4>How Countdown Timer Works</h4>
            <p>Set a time limit for your habit and watch the countdown! Complete it before time runs out to build consistency.</p>
          </div>
        </div>
      </div>
    </div>
  );
}

const styles = {
  container: {
    minHeight: '100vh',
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
  },
  content: {
    maxWidth: '700px',
    margin: '0 auto',
    padding: '20px',
    paddingTop: '80px',
  },
  header: {
    textAlign: 'center',
    marginBottom: '30px',
    color: 'white',
  },
  title: {
    fontSize: '32px',
    marginBottom: '10px',
  },
  subtitle: {
    fontSize: '14px',
    opacity: 0.9,
  },
  
  celebrationOverlay: {
    position: 'fixed',
    top: '50%',
