    overflow: 'hidden',
    marginBottom: '8px',
  },
  timerFill: {
    height: '100%',
    background: 'linear-gradient(90deg, #2ecc71, #667eea)',
    borderRadius: '4px',
    transition: 'width 0.5s ease',
  },
  timerInfo: {
    display: 'flex',
    alignItems: 'center',
    gap: '6px',
    fontSize: '11px',
    marginBottom: '8px',
    flexWrap: 'wrap',
  },
  timerRemainingText: {
    fontWeight: 'bold',
    color: '#667eea',
  },
  urgentText: {
    color: '#e74c3c',
    fontWeight: 'bold',
    animation: 'pulse 1s infinite',
  },
  timerTotalText: {
    color: '#999',
  },
  timerControls: {
    display: 'flex',
    gap: '8px',
  },
  timerBtnPlay: {
    padding: '4px 12px',
    background: '#2ecc71',
    color: 'white',
    border: 'none',
    borderRadius: '15px',
    cursor: 'pointer',
    fontSize: '10px',
    display: 'flex',
    alignItems: 'center',
    gap: '4px',
  },
  timerBtnPause: {
    padding: '4px 12px',
    background: '#f39c12',
