    borderRadius: '15px',
    cursor: 'pointer',
    fontSize: '10px',
    display: 'flex',
    alignItems: 'center',
    gap: '4px',
  },
  timerBtnReset: {
    padding: '4px 12px',
    background: '#e74c3c',
    color: 'white',
    border: 'none',
    borderRadius: '15px',
    cursor: 'pointer',
